new_css = "\n/* ===== ONTOLOGY PHASE 5 START ===== */\n\n/* ONTOLOGY LANDING */\n\n.ontology-page,\n.class-page {\n  --onto-paper: #eee7d8;\n  --onto-paper-light: #f7f1e5;\n  --onto-ink: #171510;\n  --onto-muted: #746d60;\n  --onto-gold: #9e8149;\n  --onto-line: rgba(83, 63, 29, 0.20);\n\n  min-height: 100vh;\n  color: var(--onto-ink);\n  background:\n    radial-gradient(circle at 50% 12%, rgba(255, 250, 235, .95), transparent 31%),\n    linear-gradient(180deg, #f3eddf, #eae2d2);\n}\n\n.ontology-page {\n  position: relative;\n  overflow: hidden;\n}\n\n.ontology-frame {\n  position: absolute;\n  inset: 24px;\n  z-index: 20;\n  pointer-events: none;\n  border: 1px solid rgba(139, 106, 48, .22);\n}\n\n.ontology-frame span {\n  position: absolute;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 2.5rem;\n  color: rgba(139, 106, 48, .5);\n}\n\n.ontology-frame span:nth-child(1) { top: -24px; left: -20px; transform: rotate(-45deg); }\n.ontology-frame span:nth-child(2) { top: -24px; right: -20px; transform: rotate(45deg); }\n.ontology-frame span:nth-child(3) { bottom: -24px; left: -20px; transform: rotate(-135deg); }\n.ontology-frame span:nth-child(4) { bottom: -24px; right: -20px; transform: rotate(135deg); }\n\n.ontology-nav,\n.class-topbar {\n  position: relative;\n  z-index: 30;\n  min-height: 96px;\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: center;\n  gap: 2rem;\n  padding: 1.8rem 4rem;\n  border-bottom: 1px solid var(--onto-line);\n}\n\n.ontology-back,\n.ontology-course-code,\n.class-topbar > a:first-child,\n.class-topbar > span {\n  font-size: .61rem;\n  font-weight: 500;\n  letter-spacing: .2em;\n  text-transform: uppercase;\n  color: var(--onto-muted);\n}\n\n.ontology-course-code,\n.class-topbar > span {\n  justify-self: end;\n}\n\n.ontology-brand,\n.class-brand {\n  display: flex;\n  align-items: center;\n  gap: .7rem;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.25rem;\n}\n\n.ontology-brand span {\n  width: 32px;\n  height: 32px;\n  display: grid;\n  place-items: center;\n  border: 1px solid var(--onto-line);\n  border-radius: 50%;\n}\n\n.ontology-hero {\n  position: relative;\n  min-height: 780px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden;\n  border-bottom: 3px double var(--onto-line);\n}\n\n.ontology-hero-inner {\n  position: relative;\n  z-index: 5;\n  max-width: 900px;\n  padding: 7rem 2rem;\n  text-align: center;\n}\n\n.ontology-kicker,\n.ontology-greek {\n  font-size: .65rem;\n  letter-spacing: .30em;\n  text-transform: uppercase;\n  color: var(--onto-gold);\n}\n\n.ontology-medallion {\n  width: 86px;\n  height: 86px;\n  display: grid;\n  place-items: center;\n  margin: 2.2rem auto;\n  border: 3px double rgba(137, 103, 42, .42);\n  border-radius: 50%;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 2.2rem;\n  box-shadow: 0 0 0 10px rgba(157, 125, 61, .04);\n}\n\n.ontology-hero h1 {\n  margin: 0;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: clamp(5rem, 11vw, 10rem);\n  font-weight: 400;\n  line-height: .78;\n  letter-spacing: -.05em;\n}\n\n.ontology-hero h1 em {\n  font-size: .45em;\n  font-weight: 400;\n}\n\n.ontology-greek {\n  margin-top: 2.5rem;\n}\n\n.ontology-divider {\n  width: min(380px, 75vw);\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: center;\n  gap: 1rem;\n  margin: 2.5rem auto;\n  color: var(--onto-gold);\n}\n\n.ontology-divider span {\n  height: 1px;\n  background: linear-gradient(90deg, transparent, rgba(135, 102, 43, .5), transparent);\n}\n\n.ontology-intro {\n  max-width: 640px;\n  margin: 0 auto;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.45rem;\n  line-height: 1.6;\n  color: #5e584c;\n}\n\n.ontology-sun {\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  width: min(48vw, 620px);\n  aspect-ratio: 1;\n  transform: translate(-50%, -50%);\n  border-radius: 50%;\n  background: radial-gradient(circle, rgba(226, 180, 87, .18), transparent 66%);\n  animation: ontoSun 11s ease-in-out infinite;\n}\n\n.ontology-ring {\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  aspect-ratio: 1;\n  transform: translate(-50%, -50%);\n  border: 1px solid rgba(122, 94, 43, .08);\n  border-radius: 50%;\n}\n\n.ontology-ring--one { width: min(62vw, 760px); }\n.ontology-ring--two { width: min(82vw, 1050px); }\n\n.ontology-ghost {\n  position: absolute;\n  left: 50%;\n  top: 52%;\n  transform: translate(-50%, -50%);\n  font-family: 'Cormorant Garamond', serif;\n  font-size: min(28vw, 350px);\n  font-style: italic;\n  white-space: nowrap;\n  color: rgba(100, 75, 32, .028);\n}\n\n.ontology-dust {\n  position: absolute;\n  inset: 0;\n  z-index: 4;\n  pointer-events: none;\n}\n\n.ontology-dust span {\n  position: absolute;\n  left: var(--x);\n  top: var(--y);\n  width: 2px;\n  height: 2px;\n  border-radius: 50%;\n  background: rgba(168, 126, 49, .7);\n  opacity: 0;\n  animation: ontoDust var(--duration) linear infinite;\n  animation-delay: var(--delay);\n}\n\n.ontology-classes {\n  max-width: 1280px;\n  margin: 0 auto;\n  padding: 9rem 4rem 11rem;\n}\n\n.ontology-section-heading {\n  display: grid;\n  grid-template-columns: 120px 1fr;\n  gap: 2.5rem;\n  margin-bottom: 5rem;\n}\n\n.ontology-section-number {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 6rem;\n  color: rgba(87, 65, 29, .15);\n}\n\n.ontology-section-heading p {\n  margin: .7rem 0 .3rem;\n  font-family: 'Cormorant Garamond', serif;\n  font-style: italic;\n  color: var(--onto-gold);\n}\n\n.ontology-section-heading h2 {\n  margin: 0;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: clamp(4rem, 8vw, 7rem);\n  font-weight: 400;\n  line-height: .85;\n}\n\n.ontology-class-card {\n  position: relative;\n  display: grid;\n  grid-template-columns: 180px 1fr auto;\n  align-items: center;\n  gap: 3rem;\n  min-height: 260px;\n  padding: 2.5rem 3rem;\n  border: 1px solid var(--onto-line);\n  outline: 1px solid rgba(112, 84, 35, .08);\n  outline-offset: 9px;\n  transition: transform .25s ease, box-shadow .25s ease;\n}\n\n.ontology-class-card:hover {\n  transform: translateY(-6px);\n  box-shadow: 0 25px 70px rgba(57, 42, 18, .09);\n}\n\n.ontology-class-date span {\n  display: block;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 5rem;\n  line-height: .8;\n}\n\n.ontology-class-date small,\n.ontology-class-label,\n.ontology-class-enter span {\n  font-size: .58rem;\n  font-weight: 500;\n  letter-spacing: .2em;\n  text-transform: uppercase;\n  color: var(--onto-muted);\n}\n\n.ontology-class-main h3 {\n  margin: .45rem 0 .7rem;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 2.7rem;\n  font-weight: 500;\n}\n\n.ontology-class-main p {\n  max-width: 600px;\n  margin: 0;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.2rem;\n  line-height: 1.55;\n  color: #615b50;\n}\n\n.ontology-class-enter {\n  display: flex;\n  align-items: center;\n  gap: .8rem;\n}\n\n.ontology-class-enter b {\n  font-size: 1.2rem;\n  color: var(--onto-gold);\n}\n\n.ontology-footer,\n.class-footer {\n  min-height: 175px;\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: center;\n  padding: 3rem 4rem;\n  border-top: 3px double var(--onto-line);\n  font-size: .58rem;\n  font-weight: 500;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: var(--onto-muted);\n}\n\n.ontology-footer span:nth-child(2),\n.class-footer span:nth-child(2) {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.15rem;\n  color: var(--onto-gold);\n}\n\n.ontology-footer span:last-child,\n.class-footer span:last-child {\n  justify-self: end;\n}\n\n/* CLASS PAGE */\n\n.class-page {\n  scroll-behavior: smooth;\n}\n\n.class-header {\n  position: relative;\n  overflow: hidden;\n  min-height: 650px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 6rem 2rem;\n  text-align: center;\n  border-bottom: 3px double var(--onto-line);\n}\n\n.class-header-glyph {\n  position: absolute;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: min(36vw, 460px);\n  font-style: italic;\n  color: rgba(95, 70, 29, .035);\n}\n\n.class-header > *:not(.class-header-glyph) {\n  position: relative;\n  z-index: 2;\n}\n\n.class-header-kicker {\n  font-size: .64rem;\n  font-weight: 500;\n  letter-spacing: .28em;\n  text-transform: uppercase;\n  color: var(--onto-gold);\n}\n\n.class-header h1 {\n  display: flex;\n  flex-direction: column;\n  margin: 1.5rem 0 0;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: clamp(5rem, 10vw, 9rem);\n  font-weight: 400;\n  line-height: .72;\n  letter-spacing: -.05em;\n}\n\n.class-header h1 em {\n  margin-top: .35em;\n  font-size: .5em;\n  font-weight: 400;\n}\n\n.class-header-subtitle {\n  max-width: 650px;\n  margin: 2.8rem auto 0;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.35rem;\n  line-height: 1.55;\n  color: #5d574c;\n}\n\n.class-header-ornament {\n  margin-top: 2.5rem;\n  color: rgba(140, 106, 45, .65);\n  letter-spacing: .25rem;\n}\n\n.class-layout {\n  max-width: 1440px;\n  display: grid;\n  grid-template-columns: 285px minmax(0, 1fr);\n  gap: 5rem;\n  margin: 0 auto;\n  padding: 7rem 4rem 10rem;\n}\n\n.class-index {\n  position: sticky;\n  top: 1.5rem;\n  align-self: start;\n  padding: 1.5rem 0;\n  border-top: 1px solid var(--onto-line);\n  border-bottom: 1px solid var(--onto-line);\n}\n\n.class-index > p {\n  margin: 0 0 1.2rem;\n  font-family: 'Cormorant Garamond', serif;\n  font-style: italic;\n  color: var(--onto-gold);\n}\n\n.class-index nav {\n  display: flex;\n  flex-direction: column;\n}\n\n.class-index a {\n  display: grid;\n  grid-template-columns: 34px 1fr;\n  gap: .65rem;\n  padding: .62rem 0;\n  font-size: .72rem;\n  color: #5e594f;\n  border-bottom: 1px solid rgba(88, 66, 31, .08);\n}\n\n.class-index a span {\n  color: var(--onto-gold);\n}\n\n.class-article {\n  max-width: 900px;\n}\n\n.class-section {\n  scroll-margin-top: 2rem;\n  padding: 0 0 7rem;\n  margin-bottom: 7rem;\n  border-bottom: 1px solid var(--onto-line);\n}\n\n.class-section:last-child {\n  margin-bottom: 0;\n  border-bottom: 0;\n}\n\n.class-section-heading {\n  display: grid;\n  grid-template-columns: 70px 1fr;\n  gap: 1.6rem;\n  align-items: start;\n  margin-bottom: 3rem;\n}\n\n.class-section-heading > span {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 3rem;\n  color: rgba(91, 67, 29, .2);\n}\n\n.class-section-heading p {\n  margin: .3rem 0 .4rem;\n  font-size: .61rem;\n  font-weight: 500;\n  letter-spacing: .2em;\n  text-transform: uppercase;\n  color: var(--onto-gold);\n}\n\n.class-section-heading h2 {\n  margin: 0;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: clamp(3rem, 5vw, 4.7rem);\n  font-weight: 400;\n  line-height: .9;\n  letter-spacing: -.03em;\n}\n\n.class-section > p,\n.class-lead {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.28rem;\n  line-height: 1.72;\n  color: #413e37;\n}\n\n.class-big-questions {\n  padding: 2rem 0 2.4rem;\n  margin-bottom: 2rem;\n  border-top: 3px double var(--onto-line);\n  border-bottom: 3px double var(--onto-line);\n}\n\n.class-big-questions p {\n  margin: .4rem 0;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: clamp(2.1rem, 4vw, 3.8rem);\n  line-height: 1.05;\n}\n\n.class-callout,\n.class-center-note,\n.class-maxim,\n.class-ai-note {\n  margin: 3rem 0;\n  padding: 2.2rem 2.5rem;\n  border: 1px solid var(--onto-line);\n  background: rgba(255, 251, 240, .28);\n}\n\n.class-callout span,\n.class-ai-note span {\n  display: block;\n  margin-bottom: .7rem;\n  font-size: .57rem;\n  font-weight: 500;\n  letter-spacing: .2em;\n  text-transform: uppercase;\n  color: var(--onto-gold);\n}\n\n.class-callout strong,\n.class-maxim {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.8rem;\n  font-weight: 500;\n  line-height: 1.35;\n}\n\n.class-concept-grid,\n.class-books,\n.class-info-cards {\n  display: grid;\n  gap: 1px;\n  margin: 3rem 0;\n  background: var(--onto-line);\n  border: 1px solid var(--onto-line);\n}\n\n.class-concept-grid {\n  grid-template-columns: repeat(2, 1fr);\n}\n\n.class-books,\n.class-info-cards {\n  grid-template-columns: repeat(3, 1fr);\n}\n\n.class-concept-grid > div,\n.class-books > div,\n.class-info-cards > div {\n  min-height: 150px;\n  padding: 1.7rem;\n  background: rgba(246, 239, 224, .88);\n}\n\n.class-concept-grid span,\n.class-books span,\n.class-info-cards span {\n  display: block;\n  margin-bottom: 1rem;\n  font-size: .57rem;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: var(--onto-gold);\n}\n\n.class-concept-grid strong,\n.class-books strong,\n.class-info-cards strong {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.55rem;\n  font-weight: 500;\n}\n\n.class-info-cards p {\n  font-family: 'Cormorant Garamond', serif;\n  line-height: 1.45;\n  color: #5f594d;\n}\n\n.class-center-note {\n  text-align: center;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.45rem;\n}\n\n.class-timeline {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  margin: 3rem 0;\n  border-top: 1px solid var(--onto-line);\n  border-bottom: 1px solid var(--onto-line);\n}\n\n.class-timeline div {\n  padding: 1.8rem 1.2rem;\n  border-right: 1px solid var(--onto-line);\n}\n\n.class-timeline div:last-child {\n  border-right: 0;\n}\n\n.class-timeline span {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.4rem;\n}\n\n.class-timeline p {\n  margin: .5rem 0 0;\n  font-size: .68rem;\n  color: var(--onto-muted);\n}\n\n.class-cartesian {\n  margin: 3rem auto;\n  max-width: 700px;\n  padding: 2.5rem;\n  text-align: center;\n  border: 3px double var(--onto-line);\n}\n\n.class-cartesian-god span,\n.class-cartesian-pair span,\n.class-paired-terms span {\n  display: block;\n  font-style: italic;\n  color: var(--onto-gold);\n}\n\n.class-cartesian-god strong,\n.class-cartesian-pair strong {\n  display: block;\n  margin-top: .35rem;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.6rem;\n  font-weight: 500;\n}\n\n.class-cartesian-line {\n  width: 1px;\n  height: 55px;\n  margin: 1.5rem auto;\n  background: var(--onto-line);\n}\n\n.class-cartesian-pair {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1px;\n  background: var(--onto-line);\n}\n\n.class-cartesian-pair > div {\n  padding: 1.5rem;\n  background: var(--onto-paper);\n}\n\n.class-paired-terms {\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: center;\n  gap: 1.5rem;\n  margin: 3rem 0;\n}\n\n.class-paired-terms > div {\n  padding: 2rem;\n  text-align: center;\n  border: 1px solid var(--onto-line);\n}\n\n.class-paired-terms span {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.7rem;\n}\n\n.class-paired-terms b {\n  color: var(--onto-gold);\n}\n\n.class-contrast {\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: stretch;\n  gap: 1.5rem;\n  margin: 3rem 0;\n}\n\n.class-contrast > div {\n  padding: 2.2rem;\n  border: 1px solid var(--onto-line);\n}\n\n.class-contrast > span {\n  align-self: center;\n  font-style: italic;\n  color: var(--onto-gold);\n}\n\n.class-contrast small {\n  display: block;\n  margin-bottom: .6rem;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n  color: var(--onto-muted);\n}\n\n.class-contrast strong {\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.8rem;\n  font-weight: 500;\n}\n\n.class-contrast p {\n  margin-bottom: 0;\n  color: var(--onto-muted);\n}\n\n.class-maxim {\n  text-align: center;\n  font-style: italic;\n}\n\n.class-course-map {\n  display: flex;\n  flex-wrap: wrap;\n  gap: .8rem 0;\n  align-items: center;\n}\n\n.class-course-map div {\n  display: flex;\n  align-items: center;\n}\n\n.class-course-map span {\n  padding: .8rem 1rem;\n  border: 1px solid var(--onto-line);\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.15rem;\n}\n\n.class-course-map b {\n  padding: 0 .45rem;\n  color: var(--onto-gold);\n}\n\n.class-ai-note p {\n  margin: 0;\n  font-family: 'Cormorant Garamond', serif;\n  font-size: 1.2rem;\n  line-height: 1.55;\n}\n\n.class-transcript {\n  margin-top: 2.5rem;\n  border: 1px solid var(--onto-line);\n}\n\n.class-transcript summary {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  cursor: pointer;\n  list-style: none;\n  padding: 1.4rem 1.6rem;\n  font-size: .68rem;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n\n.class-transcript summary::-webkit-details-marker {\n  display: none;\n}\n\n.class-transcript pre {\n  max-height: 720px;\n  overflow: auto;\n  margin: 0;\n  padding: 2rem;\n  border-top: 1px solid var(--onto-line);\n  white-space: pre-wrap;\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: .82rem;\n  line-height: 1.65;\n  color: #403b32;\n  background: rgba(255, 252, 244, .32);\n}\n\n@keyframes ontoSun {\n  0%, 100% { transform: translate(-50%, -50%) scale(.94); opacity: .6; }\n  50% { transform: translate(-50%, -50%) scale(1.08); opacity: 1; }\n}\n\n@keyframes ontoDust {\n  0% { transform: translate3d(0, 20px, 0); opacity: 0; }\n  15% { opacity: .32; }\n  80% { opacity: .16; }\n  100% { transform: translate3d(15px, -95px, 0); opacity: 0; }\n}\n\n@media (max-width: 950px) {\n  .class-layout {\n    grid-template-columns: 1fr;\n  }\n\n  .class-index {\n    position: static;\n  }\n\n  .class-index nav {\n    display: grid;\n    grid-template-columns: repeat(2, 1fr);\n  }\n\n  .class-books,\n  .class-info-cards {\n    grid-template-columns: 1fr;\n  }\n\n  .class-timeline {\n    grid-template-columns: repeat(2, 1fr);\n  }\n\n  .ontology-class-card {\n    grid-template-columns: 140px 1fr;\n  }\n\n  .ontology-class-enter {\n    grid-column: 2;\n  }\n}\n\n@media (max-width: 720px) {\n  .ontology-nav,\n  .class-topbar {\n    grid-template-columns: 1fr auto;\n    padding: 1.5rem 1.7rem;\n  }\n\n  .ontology-course-code,\n  .class-topbar > span {\n    display: none;\n  }\n\n  .ontology-hero {\n    min-height: 690px;\n  }\n\n  .ontology-classes,\n  .class-layout {\n    padding-left: 1.5rem;\n    padding-right: 1.5rem;\n  }\n\n  .ontology-section-heading,\n  .class-section-heading {\n    grid-template-columns: 1fr;\n  }\n\n  .ontology-class-card {\n    grid-template-columns: 1fr;\n    gap: 2rem;\n  }\n\n  .ontology-class-enter {\n    grid-column: auto;\n  }\n\n  .ontology-footer,\n  .class-footer {\n    grid-template-columns: 1fr;\n    gap: 1.3rem;\n    text-align: center;\n  }\n\n  .ontology-footer span:last-child,\n  .class-footer span:last-child {\n    justify-self: center;\n  }\n\n  .class-header {\n    min-height: 590px;\n  }\n\n  .class-index nav {\n    grid-template-columns: 1fr;\n  }\n\n  .class-concept-grid,\n  .class-timeline,\n  .class-cartesian-pair {\n    grid-template-columns: 1fr;\n  }\n\n  .class-paired-terms,\n  .class-contrast {\n    grid-template-columns: 1fr;\n  }\n\n  .class-paired-terms > b,\n  .class-contrast > span {\n    justify-self: center;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .ontology-sun,\n  .ontology-dust span {\n    animation: none !important;\n  }\n}\n\n/* ===== ONTOLOGY PHASE 5 END ===== */\n"

if start in css_text and end in css_text:
    before = css_text.split(start)[0].rstrip()
    after = css_text.split(end)[1].lstrip()
